class ExplosionDetector:
    """Recognises the Cauldron explosion (a small pop, then a broadband whoosh that turns into a deep boom, ~0.4 s).
    Looks at the last 20 frames of 9 loudness bands and checks (1) the sound got clearly louder, (2) the way every band
    rises and falls over time matches the recording (each band is compared on its own scale, so the game's volume and
    the sounds already playing don't matter) and (3) the loud part is bass-heavy like the recording (white noise, a plain
    boom or a sweep don't match)."""
    EDGES = DragonBloodDetector.EDGES
    FRAMES, TAIL = 20, 8
    MIN_RISE = 8.0                      # dB the last 6 frames must be louder than the first 6, on average
    MATCH_TIME, MATCH_SHAPE = 0.80, 0.75
    REFRACTORY = 3.0

    def __init__(self, on_heard=None, clock=time.time):
        self.on_heard, self.clock = on_heard, clock
        self.buf = np.zeros(0)
        self.count = 0
        self.last_heard = float("-inf")
        self.last_score = 0.0
        self.hist = []
        self._rate = None
        t = np.asarray(EXPLODE_TEMPLATE, dtype=float)
        self._t_time = self._z(t)
        self._t_shape = t[-self.TAIL:].mean(axis=0)

    @staticmethod
    def _z(w):
        sd = np.maximum(w.std(axis=0), 3.0)
        return ((w - w.mean(axis=0)) / sd).ravel()

    def _prep(self, rate):
        self._rate = rate
        self._block = int(round(2048 * rate / 48000.0))
        self._hop = self._block // 2
        fr = np.fft.rfftfreq(self._block, 1.0 / rate)
        self._bands = np.array([(fr >= a) & (fr < b) for a, b in zip(self.EDGES[:-1], self.EDGES[1:])], dtype=float)
        self._win = np.hanning(self._block)

    def feed(self, samples, rate):
        if rate != self._rate:
            self._prep(rate)
            self.buf, self.hist = np.zeros(0), []
        self.buf = np.concatenate([self.buf, np.asarray(samples, dtype=float)])
        while len(self.buf) >= self._block:
            p = self._bands @ (np.abs(np.fft.rfft(self.buf[:self._block] * self._win)) ** 2)
            self.buf = self.buf[self._hop:]
            self.hist.append(10.0 * np.log10(p + 1e-12))
            if len(self.hist) > self.FRAMES:
                del self.hist[0]
            self._check()

    @staticmethod
    def _corr(a, b):
        a, b = a - a.mean(), b - b.mean()
        d = float(np.linalg.norm(a) * np.linalg.norm(b))
        return float(a @ b / d) if d > 1e-9 else 0.0

    def _check(self):
        if len(self.hist) < self.FRAMES:
            return
        w = np.array(self.hist)
        if w[-6:].mean() - w[:6].mean() < self.MIN_RISE:
            return
        t = self._corr(self._z(w), self._t_time)
        sh = self._corr(w[-self.TAIL:].mean(axis=0), self._t_shape)
        self.last_score = min(t, sh)
        now = self.clock()
        if t >= self.MATCH_TIME and sh >= self.MATCH_SHAPE and now - self.last_heard >= self.REFRACTORY:
            self.count += 1
            self.last_heard = now
            if self.on_heard:
                self.on_heard(self.count)


class SoundMux:
    """Gives the same audio to several detectors."""

    def __init__(self, *dets):
        self.dets = dets

    def feed(self, samples, rate):
        for d in self.dets:
            d.feed(samples, rate)


class AudioListener:
    """Feeds a DingDetector from the sound card's loopback (needs the PyAudioWPatch package, Windows only)."""

    def __init__(self, detector):
        self.det = detector
        self.stream = self.pa = None
        self.error = None

    @staticmethod
    def available():
        return IS_WIN and pyaudio is not None

    def start(self):
        if self.stream is not None:
            return True
        if not self.available():
            if not IS_WIN:
                self.error = "Sound detection only works on Windows"
            elif IS_FROZEN:
                self.error = "This .exe was built without sound detection - rebuild it with the newest build kit"
            else:
                self.error = f"PyAudioWPatch isn't installed for this Python ({pyaudio_error})"
            return False
        try:
            self.pa = pyaudio.PyAudio()
            api = self.pa.get_host_api_info_by_type(pyaudio.paWASAPI)
            dev = self.pa.get_device_info_by_index(api["defaultOutputDevice"])
            if not dev.get("isLoopbackDevice"):
                for lb in self.pa.get_loopback_device_info_generator():
                    if dev["name"] in lb["name"]:
                        dev = lb
                        break
            ch, rate = max(1, int(dev["maxInputChannels"])), int(dev["defaultSampleRate"])

            def cb(data, frames, info, status):
                try:
                    a = np.frombuffer(data, dtype=np.int16).astype(float) / 32768.0
                    self.det.feed(a.reshape(-1, ch).mean(axis=1) if ch > 1 else a, rate)
                except Exception:
                    pass
                return (None, pyaudio.paContinue)
            self.stream = self.pa.open(format=pyaudio.paInt16, channels=ch, rate=rate, input=True,
                                       input_device_index=dev["index"], frames_per_buffer=512,
                                       stream_callback=cb)
            self.error = None
            return True
        except Exception as ex:
            self.error = f"Couldn't listen to the game sound: {ex}"
            self.stop()
            return False

    def stop(self):
        try:
            if self.stream is not None:
                self.stream.stop_stream()
                self.stream.close()
        except Exception:
            pass
        try:
            if self.pa is not None:
                self.pa.terminate()
        except Exception:
            pass
        self.stream = self.pa = None


def precise_sleep(sec):
    """time.sleep is only accurate to ~15 ms on Windows: sleep most of it, spin the last 2 ms."""
    if sec <= 0:
        return
    end = time.perf_counter() + sec
    if sec > 0.004:
        time.sleep(sec - 0.003)
    while time.perf_counter() < end:
        pass


if IS_WIN:
    class _KEYBDINPUT(ctypes.Structure):
        _fields_ = [("wVk", wintypes.WORD), ("wScan", wintypes.WORD), ("dwFlags", wintypes.DWORD),
                    ("time", wintypes.DWORD), ("dwExtraInfo", ctypes.c_size_t)]

    class _MOUSEINPUT(ctypes.Structure):
        _fields_ = [("dx", wintypes.LONG), ("dy", wintypes.LONG), ("mouseData", wintypes.DWORD),
                    ("dwFlags", wintypes.DWORD), ("time", wintypes.DWORD), ("dwExtraInfo", ctypes.c_size_t)]

    class _INPUTUNION(ctypes.Union):
        _fields_ = [("ki", _KEYBDINPUT), ("mi", _MOUSEINPUT)]

    class _INPUT(ctypes.Structure):
        _fields_ = [("type", wintypes.DWORD), ("u", _INPUTUNION)]

    u32.SendInput.argtypes, u32.SendInput.restype = [wintypes.UINT, ctypes.POINTER(_INPUT), ctypes.c_int], wintypes.UINT
    u32.MapVirtualKeyW.argtypes, u32.MapVirtualKeyW.restype = [wintypes.UINT, wintypes.UINT], wintypes.UINT

    def _send_input(inp):
        u32.SendInput(1, ctypes.byref(inp), ctypes.sizeof(inp))

    def send_key(name, up=False):
        sc = next((c for c, n in SCAN_HOTBAR.items() if n == name), None)
        if sc is not None:                                   # "-" / "=": sent by PLACE (scan code), so every keyboard layout presses the right slot
            _send_input(_INPUT(1, _INPUTUNION(ki=_KEYBDINPUT(0, sc, 8 | (2 if up else 0), 0, TRAIN_TAG))))
            return
        vk = SEND_VK[name]
        inp = _INPUT(1, _INPUTUNION(ki=_KEYBDINPUT(vk, u32.MapVirtualKeyW(vk, 0), 2 if up else 0, 0, TRAIN_TAG)))
        _send_input(inp)

    def send_click(up=False):
        inp = _INPUT(0, _INPUTUNION(mi=_MOUSEINPUT(0, 0, 0, 4 if up else 2, 0, TRAIN_TAG)))
        _send_input(inp)

    def send_scan_key(scan, up=False):
        """A hardware-style key press: only the scan code with KEYEVENTF_SCANCODE (no virtual key), the way a real keyboard reports it."""
        _send_input(_INPUT(1, _INPUTUNION(ki=_KEYBDINPUT(0, int(scan), 8 | (2 if up else 0), 0, TRAIN_TAG))))

    def send_rclick(up=False):
        inp = _INPUT(0, _INPUTUNION(mi=_MOUSEINPUT(0, 0, 0, 16 if up else 8, 0, TRAIN_TAG)))
        _send_input(inp)

    def send_raw_key(vk, ext=0, up=False, tag=TRAIN_TAG):
        """A key by its virtual key."""
        fl = (2 if up else 0) | (1 if ext else 0)
        _send_input(_INPUT(1, _INPUTUNION(ki=_KEYBDINPUT(int(vk), u32.MapVirtualKeyW(int(vk), 0), fl, 0, tag))))

    def close_foreground_window():
        """What Alt+F4 does: asks the window in front to close."""
        U = ctypes.WinDLL("user32")
        U.GetForegroundWindow.restype = wintypes.HWND
        U.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
        h = U.GetForegroundWindow()
        if h:
            U.PostMessageW(h, 0x112, 0xF060, 0)               # WM_SYSCOMMAND, SC_CLOSE

    def send_raw_scan(scan, ext=False, up=False, tag=TRAIN_TAG):
        """A key by its PLACE on the keyboard (scan code)."""
        fl = (2 if up else 0) | (1 if ext else 0)
        _send_input(_INPUT(1, _INPUTUNION(ki=_KEYBDINPUT(int(u32.MapVirtualKeyW(int(scan), 3)), int(scan), fl, 0, tag))))


    def _mouse_move_abs(x, y):
        vx, vy, vw, vh = (u32.GetSystemMetrics(i) for i in (76, 77, 78, 79))         # the whole virtual desktop
        vw, vh = max(2, vw), max(2, vh)
        nx, ny = int((x - vx) * 65535 / (vw - 1)) + 1, int((y - vy) * 65535 / (vh - 1)) + 1
        _send_input(_INPUT(0, _INPUTUNION(mi=_MOUSEINPUT(nx, ny, 0, 0x0001 | 0x8000 | 0x4000, 0, TRAIN_TAG))))

    def _mouse_move_rel(dx, dy):
        _send_input(_INPUT(0, _INPUTUNION(mi=_MOUSEINPUT(dx, dy, 0, 0x0001, 0, TRAIN_TAG))))

    def move_cursor(x, y, nudge=True):
        """Moves the cursor like a real mouse does (the game only learns where the cursor is from mouse-move events;
        a plain SetCursorPos leaves it clicking at the OLD spot). nudge: a 1 px wiggle afterwards, to be sure."""
        x, y = int(x), int(y)
        u32.SetCursorPos(x, y)
        _mouse_move_abs(x, y)
        if nudge:
            time.sleep(0.01)
            _mouse_move_rel(1, 0)
            time.sleep(0.01)
            _mouse_move_rel(-1, 0)

    def timer_resolution(on):
        try:
            (ctypes.windll.winmm.timeBeginPeriod if on else ctypes.windll.winmm.timeEndPeriod)(1)
        except Exception:
            pass
else:
    def move_cursor(x, y, nudge=True):
        pass

    def send_key(name, up=False):
        pass

    def send_click(up=False):
        pass

    def send_rclick(up=False):
        pass

    def send_scan_key(scan, up=False):
        pass

    def send_raw_key(vk, ext=0, up=False, tag=None):
        pass

    def send_raw_scan(scan, ext=False, up=False, tag=None):
        pass

    def close_foreground_window():
        pass

    def timer_resolution(on):
        pass


BREW_OUT = "ran out of ingredients"
BREW_BOOM = "the cauldron exploded"


def discord_ok(url):
    """Only real Discord webhook links are ever posted to."""
    return bool(re.match(r"^https://(?:(?:ptb|canary)\.)?discord(?:app)?\.com/api(?:/v\d+)?/webhooks/\d+/[\w-]+/?(?:\?.*)?$", str(url).strip()))


def discord_embed(title, text, color, footer="Assist Tool"):
    return {"embeds": [{"title": title, "description": text, "color": color, "footer": {"text": footer},
                        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S.000Z", time.gmtime())}]}


def discord_send(url, payload, timeout=10):
    """POST the payload to a Discord webhook. Returns (ok, message)."""
    url = str(url).strip()
    if not url:
        return False, "No webhook link set"
    if not discord_ok(url):
        return False, "That isn't a Discord webhook link"
    try:
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), method="POST",
                                     headers={"Content-Type": "application/json", "User-Agent": "AssistTool (webhook, 1.0)"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return (200 <= r.status < 300), f"Sent (HTTP {r.status})"
    except urllib.error.HTTPError as e:
        return False, f"Discord said HTTP {e.code}" + (" - the link was deleted or is wrong" if e.code in (401, 404) else "")
    except Exception as e:
        return False, f"Couldn't reach Discord: {type(e).__name__}"


def discord_send_image(url, payload, png, name="screenshot.png", timeout=20):
    """Like discord_send, but with a picture attached (the embed shows it). Returns (ok, message)."""
    url = str(url).strip()
    if not url:
        return False, "No webhook link set"
    if not discord_ok(url):
        return False, "That isn't a Discord webhook link"
    try:
        emb = payload["embeds"][0]
        emb["image"] = {"url": "attachment://" + name}
        boundary = "----AssistTool" + hashlib.md5(png[:64] + str(time.time()).encode()).hexdigest()
        parts = [("--%s\r\nContent-Disposition: form-data; name=\"payload_json\"\r\nContent-Type: application/json\r\n\r\n" % boundary).encode(),
                 json.dumps(payload).encode("utf-8"),
                 ("\r\n--%s\r\nContent-Disposition: form-data; name=\"files[0]\"; filename=\"%s\"\r\nContent-Type: image/png\r\n\r\n" % (boundary, name)).encode(),
                 png, ("\r\n--%s--\r\n" % boundary).encode()]
        req = urllib.request.Request(url, data=b"".join(parts), method="POST",
                                     headers={"Content-Type": "multipart/form-data; boundary=" + boundary,
                                              "User-Agent": "AssistTool (webhook, 1.0)"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return (200 <= r.status < 300), f"Sent (HTTP {r.status})"
    except urllib.error.HTTPError as e:
        return False, f"Discord said HTTP {e.code}" + (" - the link was deleted or is wrong" if e.code in (401, 404) else "")
    except Exception as e:
        return False, f"Couldn't reach Discord: {type(e).__name__}"


def game_window_rect(title="Roblox"):
    """(left, top, width, height) of the game window's client area on the screen, or None when the Roblox game isn't the
    window in front."""
    if not IS_WIN:
        return None
    try:
        h = u32.GetForegroundWindow()
        if not h or not is_roblox_window(h):
            return None                                      # (the Roblox game itself has to be the window in front: not a browser tab that says Roblox)
        rc = wintypes.RECT()
        u32.GetClientRect(h, ctypes.byref(rc))
        pt = wintypes.POINT(0, 0)
        u32.ClientToScreen(h, ctypes.byref(pt))
        if rc.right - rc.left < 50 or rc.bottom - rc.top < 50:
            return None
        return int(pt.x), int(pt.y), int(rc.right - rc.left), int(rc.bottom - rc.top)
    except Exception:
        return None


def screenshot_png(rect=None):
    """PNG bytes of the screen rect (left, top, w, h), or of the whole main screen."""
    with mss.mss() as sct:
        box = ({"left": rect[0], "top": rect[1], "width": rect[2], "height": rect[3]} if rect else sct.monitors[1])
        shot = sct.grab(box)
        img = Image.frombytes("RGB", shot.size, shot.rgb)
    out = io.BytesIO()
    img.save(out, "PNG", optimize=False)
    return out.getvalue()


# ---------------- Gate: the shortcut boxes next to the game's gate prompt, pinned gates, gate keybinds ----------------
GATE_BASE = ("Sigil", "Skycastle", "Snail")                                    # pinned by default
GATE_AREAS = (("Forest", 5), ("Desert", 5), ("Deepforest", 5), ("Shore", 4), ("Tundra", 7), ("Canyon", 9))     # the boxes on the right, in this order
GATE_PAGE_ORDER = ("Desert", "Forest", "Shore", "Tundra", "Deepforest", "Canyon")                          # the order of the "Unpinned Gates Location" list
GATE_RANDOM = ("Sigil", "Skycastle", "Snail", "Deepforest", "Forest", "Tundra", "Shore", "Desert", "Canyon")     # the random gate picks one of these
GATE_ICON_PNG = ""


def gate_icon():
    """The picture for Extras > Other Stuff > Gate."""
    return Image.open(io.BytesIO(base64.b64decode(GATE_ICON_PNG))).convert("RGBA")


GATE_ROWS = 6                                                                  # boxes shown at once in a column (more: scroll)
GATE_RAND_KEY = {"id": 0x26, "label": "L"}                                     # the random gate key by default (scan code of L)


def gate_spots(area):
    n = dict(GATE_AREAS).get(area, 0)
    return [f"{area} {i}" for i in range(1, n + 1)]


def gate_all():
    names = list(GATE_BASE)
    for a in GATE_PAGE_ORDER:
        names += gate_spots(a)
    return names


GATE_ALL = tuple(gate_all())


def clean_gates(data):
    """{"pinned": [gate names], "keys": {gate name: {"id", "label"}}, "rand": {"id", "label"} | None}."""
    out = {"pinned": list(GATE_BASE), "keys": {}, "rand": dict(GATE_RAND_KEY)}
    if not isinstance(data, dict):
        return out
    if isinstance(data.get("pinned"), list):
        seen = []
        for n in data["pinned"]:
            if isinstance(n, str) and n in GATE_ALL and n not in seen:
                seen.append(n)
        out["pinned"] = seen
    if isinstance(data.get("keys"), dict):
        for n, d in data["keys"].items():
            k = _clean_key(d) if isinstance(d, dict) else None
            if n in GATE_ALL and k:
                out["keys"][n] = k
    if "rand" in data:
        out["rand"] = _clean_key(data["rand"]) if isinstance(data.get("rand"), dict) else None
    return out


def build_gatemap(g):
    """{pressed key id: gate name, or "random"}."""
    m = {}
    for n, k in (g.get("keys") or {}).items():
        m[k["id"]] = n
    if g.get("rand"):
        m[g["rand"]["id"]] = "random"
    return m


def gate_pick_random():
    import random
    return random.choice(GATE_RANDOM)


def gate_type_run(name, press, sleep=time.sleep, allowed=lambda: True, slash=0.04, hold=0.004, gap=0.003, pre_enter=0.025):
    """What a gate shortcut / keybind does: the chat key (/), the gate's name, Enter - pressed one after the other. press(token, up) presses one
    key: "/", a letter, a digit, " " or "enter". Returns "" or the reason it didn't."""
    if not allowed():
        return "the game window isn't in front"
    press("/", False); sleep(hold); press("/", True)
    sleep(slash)                                                                # (the chat box needs a moment to open: the only wait that matters)
    for ch in str(name).lower():
        if ch not in "abcdefghijklmnopqrstuvwxyz0123456789 ":
            continue
        press(ch, False); sleep(hold); press(ch, True); sleep(gap)
    sleep(pre_enter)
    press("enter", False); sleep(hold); press("enter", True)
    return ""


class GateMenu:
    """What the gate shortcut boxes show (no windows here, so it can be tested): the pinned gates in a left column, the areas (Forest, Desert ...)
    in a right column; an area replaces the right column with its numbers (Forest 1 ... Forest 5) and a Back box. Both columns scroll."""

    def __init__(self, pinned):
        self.pinned = list(pinned)
        self.area = None
        self.sel = 0
        self.off = {"L": 0, "R": 0}

    def set_pinned(self, pinned):
        self.pinned = list(pinned)
        self.off["L"] = max(0, min(self.off["L"], max(0, len(self.pinned) - GATE_ROWS)))
        self.sel = min(self.sel, max(0, len(self.ring()) - 1))

    def left(self):
        return [("pin", n, n) for n in self.pinned]

    def right(self):
        if self.area is None:
            return [("area", a, a) for a, _ in GATE_AREAS]
        return [("spot", n, n) for n in gate_spots(self.area)] + [("back", "< Back", "")]

    def ring(self):
        return self.left() + self.right()

    def reset(self):
        self.area, self.sel, self.off = None, 0, {"L": 0, "R": 0}
        if not self.pinned:
            self.sel = 0

    def _fit(self):
        """Scroll the column of the selected box so the box is on screen."""
        nl = len(self.left())
        i = self.sel
        col, idx = ("L", i) if i < nl else ("R", i - nl)
        if idx < self.off[col]:
            self.off[col] = idx
        elif idx >= self.off[col] + GATE_ROWS:
            self.off[col] = idx - GATE_ROWS + 1

    def move(self, d):
        n = len(self.ring())
        if n:
            self.sel = (self.sel + d) % n
            self._fit()

    def move2(self, dx, dy):
        """W / A / S / D: up / down move inside a column (round the end), left / right jump to the other column (same row, or the last one)."""
        nl = len(self.left())
        if not self.ring():
            return
        i = self.sel
        col, idx = ("L", i) if i < nl else ("R", i - nl)
        items = self.left() if col == "L" else self.right()
        if dy:
            idx = (idx + dy) % len(items)
        elif dx > 0 and col == "L" and self.right():
            col, idx = "R", min(idx, len(self.right()) - 1)
        elif dx < 0 and col == "R" and nl:
            col, idx = "L", min(idx, nl - 1)
        self.sel = idx if col == "L" else nl + idx
        self._fit()

    def scroll(self, col, d):
        n = len(self.left() if col == "L" else self.right())
        self.off[col] = max(0, min(self.off[col] + d, max(0, n - GATE_ROWS)))

    def activate(self, item):
        """item = a (kind, label, gate name) of ring(). Returns the gate name to go to, or None (an area opened / back)."""
        kind, label, name = item
        if kind in ("pin", "spot"):
            return name
        if kind == "area":
            self.area = name
            self.off["R"] = 0
            self.sel = len(self.left())
            return None
        if kind == "back":
            a, self.area = self.area, None
            self.off["R"] = 0
            names = [x[1] for x in self.right()]
            self.sel = len(self.left()) + (names.index(a) if a in names else 0)
            self._fit()
        return None

    def press(self):
        r = self.ring()
        return self.activate(r[self.sel]) if r and 0 <= self.sel < len(r) else None

    def back(self):
        if self.area is not None:
            self.activate(("back", "", ""))


def instant_menu_run(key_fn, allowed, sleep=time.sleep):
    """Instant Menu: the \\ key, Enter, the \\ key again - pressed one after the other, each one let go before the next. Returns a message."""
    if not allowed():
        return "the game window isn't in front"
    for name in ("\\", "enter", "\\"):
        key_fn(name, False)
        sleep(0.012)
        key_fn(name, True)
        sleep(0.025)
    return ""


