# GUI (Scroom skin)
# ----------------------------------------------------------------------------
UI_FONT_PX = 12          # text size in pixels - try 11-13 once Manufaktur is installed
UI_FONT_FAMILY = None    # None = use Manufaktur if it can be found, else Segoe UI

# palette sampled straight from the mockup
PARCH, GREYT, BROWN = "#d7cbbf", "#b1a79d", "#423529"
def climb_paused(app):
    """True while the mana drains slowly (the player is climbing) or Space was double-tapped while it drained at a climbing speed."""
    try:
        if getattr(getattr(app, "inputs", None), "_climb", False) is True:
            return True
        d = getattr(app, "slow_drain", None)
        return d is not None and d.blocking(time.time()) is True
    except Exception:
        return False


def keys_off(app):
    """Every keybind / Block Run / AutoHotkey is off: typing in the chat, the Esc menu, or climbing."""
    return getattr(app, "chat_open", False) is True or climb_paused(app)


CLIMB_CONFIRM = 1.0                         # seconds after Space twice in which a climbing-speed mana drain has to be seen
EMPTY_MANA = 1.0                            # % - at or below this the mana is empty
CLIMB_CHECK = 0.3                           # ... and how long a steady fall has to be seen for (after Space twice, so the look is short and a bit looser)
CLIMB_END = 5.0                             # seconds without the mana falling at all after which a climb is over (Space ends it earlier)
RB_VK = {"w": 0x57, "s": 0x53, "f": 0x46, "q": 0x51, "g": 0x47, "up": 0x26, "down": 0x28}
RB_KEYS = {0x57: "w", 0x53: "s", 0x41: "a", 0x44: "d", 0x51: "q", 0x46: "f", 0x47: "g"}      # the keys Block Run looks at
RB_SWALLOW = ("w", "s", "q", "f")                                                              # ... and takes (the others pass through)


class RunBlock:
    """The all-directional Block Run AutoHotkey script. handle(key, down) is one of its hotkeys; send(name, up) presses a key for the game,
    sleep(ms) waits. W / S / F / Q are taken by the tool (the caller swallows them); A / D / G only pass through and are tracked."""
    TAP, FIRST, DBL, RUNTAP, GAP = 180, 400, 500, 200, 10     # tapThreshold, firstHoldThreshold, doubleTapWindow, runTapWindow, runGap (ms)

    def __init__(self, send, sleep, phys=None, clock=None, gate=None):
        self._send, self.sleep = send, sleep
        self.gate = gate                                           # () -> True while Block Run may act; else a key is only sent as it is
        self.vdown = {}                                            # the keys the tool is holding down for the game right now (insertion order)
        self.phys = phys or (lambda: (False, False, False))
        self.clock = clock or (lambda: time.perf_counter() * 1000.0)
        self.clear()

    def clear(self):
        self.lastA = self.lastD = self.lastS = self.lastW = -10000.0
        self.dashing = self.fDown = self.blockMode = 0
        self.cast_clicked = False
        self.wDown = self.aDown = self.sDown = self.dDown = 0
        self.trick = self.walkEntered = self.upHeld = self.downHeld = self.wIsSecond = 0
        self.wPressTime = 0.0

    def send(self, name, up=False):
        if name != "click":                                        # (the mouse button is let go by the Cast Run when the user lets go)
            if up:
                self.vdown.pop(name, None)
            else:
                self.vdown[name] = True
        self._send(name, up)

    def reset(self, hand_back=True):
        """Block Run goes off (slow mana drain / climbing): EVERY key the tool is still holding down for the game is let go (no leftover
        arrow / W / S / F / Q); the W / S / F you really hold go back to the game."""
        w, s, f = (tuple(self.phys()) + (False, False, False))[:3]
        self.clear()
        held = list(self.vdown)
        for k in ("w", "up", "down", "s", "f", "q"):               # (the usual ones first, then anything else)
            if k in held:
                self.send(k, True)
        for k in held:
            if k in self.vdown:
                self.send(k, True)
        self.vdown.clear()
        if hand_back and held:
            self.sleep(30)
            w, s, f = (tuple(self.phys()) + (False, False, False))[:3]      # (look again: you may have let go meanwhile)
            for k, down in (("w", w), ("s", s), ("f", f)):
                if k in held and not down:
                    self.send(k, True)                                       # a key you let go must not stay held for the game
                    self.vdown.pop(k, None)
        if hand_back:
            if w and "w" in held:                                  # (only a key the tool had let go: the game still needs it held)
                self.send("w", False)
            if s and "s" in held:
                self.send("s", False)
            if f and "f" in held:
                self.send("f", False)

    def handle(self, key, down):
        if self.gate is not None and not self.gate():
            if key in ("w", "s", "f", "q"):                        # (switched off - climbing: W sends W, S sends S ... nothing else)
                self.send(key, not down)
            return
        getattr(self, ("on_" if down else "off_") + key)()

    def _exit_sprint(self):
        for k in ("up", "down", "s", "w"):
            self.send(k, True)
        self.trick = self.walkEntered = self.wIsSecond = self.upHeld = self.downHeld = 0
        if self.wDown:
            self.send("w", False)
        if self.sDown:
            self.send("s", False)

    # ---- W ----
    def on_w(self):
        if self.wDown:
            return
        self.wDown = 1
        self.wPressTime = self.clock()
        self.wIsSecond = 1 if self.wPressTime - self.lastW <= self.DBL else 0
        self.lastW = self.wPressTime
        if self.trick:
            if self.wIsSecond:
                if self.upHeld:
                    self.send("up", True)
                    self.upHeld = 0
                self.send("w", True); self.sleep(15)
                self.send("w", False); self.sleep(15)
                self.send("w", True); self.sleep(15)
                self.send("w", False)
                self.walkEntered = 0
            self.update()
        else:
            self.send("w", False)

    def off_w(self):
        self.wDown = 0
        needed = self.TAP if self.wIsSecond else self.FIRST
        if self.trick:
            self.update()
        elif (self.aDown or self.dDown or self.sDown) and self.clock() - self.wPressTime >= needed:
            self.enter_trick()
            if self.trick:
                self.walkEntered = 0 if self.wIsSecond else 1
        else:
            self.send("w", True)

    # ---- S ----
    def on_s(self):
        if self.sDown:
            return
        self.sDown = 1
        now = self.clock()
        dbl = 1 if now - self.lastS <= self.RUNTAP else 0
        self.lastS = now
        if self.trick:
            self.update()
        elif self.wDown:
            self.enter_trick()
        elif dbl:
            self.lastS = -10000.0
            self.start_run()
        else:
            self.send("s", False)

    def off_s(self):
        self.sDown = 0
        if self.trick:
            self.update()
        else:
            self.send("s", True)

    # ---- A / D ----
    def on_a(self):
        if self.aDown:
            return
        self.aDown = 1
        now = self.clock()
        dbl = 1 if now - self.lastA <= self.RUNTAP else 0
        self.lastA = now
        if self.trick:
            self.update()
        elif dbl and not self.wDown:
            self.lastA = -10000.0
            self.start_run()

    def off_a(self):
        self.aDown = 0
        if self.trick:
            self.update()

    def on_d(self):
        if self.dDown:
            return
        self.dDown = 1
        now = self.clock()
        dbl = 1 if now - self.lastD <= self.RUNTAP else 0
        self.lastD = now
        if self.trick:
            self.update()
        elif dbl and not self.wDown:
            self.lastD = -10000.0
            self.start_run()

    def off_d(self):
        self.dDown = 0
        if self.trick:
            self.update()

    # ---- Q (dash) ----
    def on_q(self):
        if not self.trick:
            self.send("q", False)
            return
        if self.dashing:
            return
        self.dashing = 1
        if not self.wDown:
            self.send("w", True)
            if self.sDown:
                self.send("s", False)
        self.sleep(15)
        self.send("q", False)

    def off_q(self):
        self.send("q", True)
        if self.dashing:
            self.dashing = 0
            self.sleep(40)
            if self.trick:
                self._exit_sprint()

    # ---- G (mana charge ends the sprint) ----
    def on_g(self):
        if self.trick:
            self._exit_sprint()

    def off_g(self):
        pass

    # ---- F (block) ----
    def on_f(self):
        if self.fDown:
            return
        self.fDown = 1
        if self.trick:
            self.blockMode = 1
            self.send("w", True); self.send("w", False); self.sleep(1)
            self.send("w", True); self.sleep(1)
            self.send("f", False); self.sleep(10)
            self.send("w", False)
            if not self.wDown:
                self.send("up", False); self.sleep(self.GAP)
                self.send("up", True)
                self.upHeld = 0
            if self.downHeld:
                self.send("down", True); self.sleep(15)
                self.send("down", False)
        elif self.wDown:
            self.blockMode = 2
            self.send("w", True); self.send("w", False); self.sleep(1)
            self.send("w", True); self.sleep(1)
            self.send("f", False); self.sleep(10)
            self.send("w", False)
        else:
            self.blockMode = 0
            self.send("f", False)

    def off_f(self):
        self.fDown = 0
        self.send("f", True)
        if self.blockMode:
            self.sleep(10)
            if self.blockMode == 2 and not self.wDown and not self.trick:
                self.send("w", True)
        self.blockMode = 0

    # ---- Cast Run (360): the same as F, but the spell is cast instead of F being pressed ----
    def on_cast(self):
        """A spell is cast while running: W + cast = a forward cast, S + cast (backward run) = a backward cast, A / D too. The click goes down
        here; the caller lets it go when the user lets go of the mouse button. Returns True when the click was sent."""
        self.cast_clicked = False
        if not (self.trick or self.wDown):
            self.send("click", False)                               # (not running: a plain cast)
            self.cast_clicked = True
            return True
        self.send("w", True); self.send("w", False); self.sleep(1)
        self.send("w", True); self.sleep(1)
        self.send("click", False)
        self.cast_clicked = True
        self.sleep(10)
        self.send("w", False)
        if self.trick:
            if not self.wDown:
                self.send("up", False); self.sleep(self.GAP)
                self.send("up", True)
                self.upHeld = 0
            if self.downHeld:
                self.send("down", True); self.sleep(15)
                self.send("down", False)
        elif not self.wDown:
            self.send("w", True)
        return True

    # ---- logic ----
    def start_run(self):
        if self.sDown and not self.wDown:
            self.send("down", False)
            self.downHeld = 1
        self.send("w", False); self.send("w", True)           # (a quick W tap)
        self.sleep(self.GAP)
        self.send("w", False)
        self.enter_trick(self.GAP)

    def enter_trick(self, hold=40):
        self.trick = 1
        self.walkEntered = 0
        self.send("s", True)
        if self.sDown and not self.wDown and not self.downHeld:
            self.send("down", False)
            self.downHeld = 1
        self.send("up", False)
        self.sleep(hold)
        self.send("up", True)
        self.upHeld = 0
        self.update()

    def update(self):
        if not (self.wDown or self.aDown or self.sDown or self.dDown):
            self.exit_trick()
            return
        want_up = bool(self.wDown and not self.sDown)
        want_down = bool(self.sDown and not self.wDown)
        if want_up and not self.upHeld:
            self.send("up", False)
            self.upHeld = 1
        elif not want_up and self.upHeld:
            self.send("up", True)
            self.upHeld = 0
        if want_down and not self.downHeld:
            self.send("down", False)
            self.downHeld = 1
        elif not want_down and self.downHeld:
            self.send("down", True)
            self.downHeld = 0

    def exit_trick(self):
        for k in ("w", "up", "down", "s"):
            self.send(k, True)
        self.trick = self.walkEntered = self.upHeld = self.downHeld = 0


class SlowDrain:
    """Detects a slow mana drain: the mana % keeps falling steadily at lo..hi % per second (a straight line, a little reading noise allowed;
    no sudden drop like a cast, no charging). feed(now, pct) with every mana reading (None = the bar can't be read: starts over)."""

    NOISE = 2.5                            # the largest distance (in %) of a reading from the straight line (the bar is read in steps of 1-2 %)
    STEP_RATE = 25.0                       # no single reading may drop faster than this many % per second (a cast; a reading is ~0.25 s)

    def __init__(self, cfg_settings):
        self.S = cfg_settings
        self.pts = []                      # (time, mana %) of the last second or so
        self.active = False
        self.rate = 0.0                    # % per second of the window (for the log / a later display)
        self.last_active = self.last_feed = -1e9

    def _num(self, k, d):
        try:
            return float(self.S.get(k, d))
        except (TypeError, ValueError):
            return d

    def reset(self):
        self.pts.clear()
        self.active, self.rate = False, 0.0

    @staticmethod
    def fit(pts):
        """(fall in % per second of the straight line through the readings, the largest distance from it, the fastest single step down in % per second)
        or None. The readings come 4-20 times a second, so a step is judged by the time it took (at least 0.25 s)."""
        if len(pts) < 2:
            return None
        ts = np.array([t for t, _ in pts]) - pts[0][0]
        vs = np.array([v for _, v in pts])
        if ts[-1] <= 0:
            return None
        k, c = np.polyfit(ts, vs, 1)
        resid = float(np.max(np.abs(vs - (k * ts + c))))
        dts = np.maximum(ts[1:] - ts[:-1], 0.25)
        step = float(np.max((vs[:-1] - vs[1:]) / dts))
        return -float(k), resid, step

    def _window(self, now, secs):
        pts = [(t, v) for t, v in self.pts if now - t <= secs + 0.25]
        if len(pts) < (2 if secs < 0.5 else 3) or pts[-1][0] - pts[0][0] < secs * 0.6 or now - self.last_feed > 0.7:
            return None                                    # (a short look can do with two readings: they may come only 4 times a second)
        return pts

    def _is_drain(self, pts, short=False):
        f = self.fit(pts)
        if f is None or pts[-1][1] <= 0.5:
            return False, 0.0
        rate, resid, step = f
        lo, hi = self._num("climb_rate_lo", 3.5), self._num("climb_rate_hi", 10.0)
        if short:
            lo, hi = lo * 0.5, hi * 1.6                       # (a short look sees only a step or two of the bar: the range is wider)
        return (lo <= rate <= hi and resid <= self.NOISE and step <= self.STEP_RATE), rate

    def climbing(self, now, secs=None):
        """A short look (CLIMB_CHECK s): is the mana falling like a climb right now?"""
        secs = CLIMB_CHECK if secs is None else secs
        pts = self._window(now, secs)
        return bool(pts and self._is_drain(pts, secs < 0.5)[0])

    def empty(self, now):
        """The mana has run out (the latest reading is about 0): a climb is over, Block Run is back at once."""
        return bool(self.pts and self.pts[-1][1] <= EMPTY_MANA and now - self.last_feed < 0.7)

    def falling(self, now, secs=1.0):
        """Is the mana still falling at all (a climb that has gone on: the reading may be noisy, or the mana nearly empty)?"""
        pts = self._window(now, secs)
        if not pts:
            return False
        if pts[-1][1] <= 2.0:
            return True
        f = self.fit(pts)
        return bool(f and f[0] >= max(0.5, self._num("climb_rate_lo", 3.5) * 0.25) and f[2] <= self.STEP_RATE * 1.5)

    def blocking(self, now, hold=0.6):
        """True while a slow drain is going on (readings still coming in) and for `hold` seconds after the last time it was seen."""
        return (self.active and now - self.last_feed < 0.6) or now - self.last_active < hold

    def feed(self, now, pct):
        self.last_feed = now
        if pct is None:
            self.reset()
            return False
        secs = max(0.3, self._num("climb_rate_win", 0.6))
        self.pts.append((now, float(pct)))
        while self.pts and now - self.pts[0][0] > max(secs, 0.7) + 0.4:
            self.pts.pop(0)
        pts = self._window(now, secs)
        ok, self.rate = self._is_drain(pts) if pts else (False, 0.0)
        self.active = bool(ok)
        if self.active:
            self.last_active = now
        if float(pct) <= EMPTY_MANA:
            self.active, self.last_active = False, -1e9         # (no mana left: no drain, and no waiting before Block Run is back)
        return self.active


AC_KEY_WAIT = 0.12                         # seconds after a hotbar key press in which the autoclicker doesn't click
TAN, TAN_HI, TAN_DN = "#d8bca1", "#e8d2bb", "#c4a688"
ORANGE, CREAM = "#e8ad72", "#ffdda2"
OKGREEN, DIM = "#4f8a2b", "#8d8379"
VIR_BOX = "#8ec8ff"                        # name box of a Viribus spell: its key casts it and holds F
GREEN_BOX = "#a3d484"                      # M2 box: M1 and M2 DON'T share; name box: the move unequips after use

WIN_W, WIN_H = ART.BG_SIZE                 # 387 x 1034
PAGE_X, PAGE_Y, PAGE_W, PAGE_H = 37, 247, 313, 565      # page area inside the frame
WIN_MIN_H = 680                                           # the window can be dragged shorter / taller than the art (bottom edge)
BG_CUT_TOP, BG_CUT_BOT, BG_GRIP = 300, 760, 60
BG_CORNER, BG_CORNER_X = 210, 70                          # the bottom corner ornaments are grips too            # the plain parchment between these two rows is what gets stretched


def window_height_ok(h, screen_h=None, sc=1.0):
    """A wanted window height (in unscaled units) -> the nearest usable one (never taller than the screen when that is known)."""
    try:
        h = int(round(float(h)))
    except (TypeError, ValueError):
        h = WIN_H
    top = max(WIN_MIN_H, int((int(screen_h) - 40) / float(sc or 1.0))) if screen_h else 4000
    return max(WIN_MIN_H, min(h, top))


# ---- the whole window can be scaled (drag a corner): everything the window itself is made of is multiplied at the Tk border ----
UI_SC = [1.0]                    # the scale in use (1.0 = as drawn; every patched function below does nothing then)
UI_SC_MIN, UI_SC_MAX = 0.8, 2.5
APP_ROOT = [None]                # the main window: only its widgets are scaled (the overlays on the screen never are)


def sc_ok(sc, screen_h=None):
    """A wanted scale -> a usable one (the window must still fit the screen at its minimum height)."""
    try:
        sc = float(sc)
    except (TypeError, ValueError):
        sc = 1.0
    if not (sc == sc):
        sc = 1.0
    top = UI_SC_MAX
    if screen_h:
        top = min(top, max(1.0, (int(screen_h) - 40) / float(WIN_MIN_H)))
    sc = max(UI_SC_MIN, min(sc, top))
    return 1.0 if abs(sc - 1.0) < 0.02 else round(sc, 3)


def S(v):
    return int(round(v * UI_SC[0]))


def _sc_num(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return S(v)
    if isinstance(v, (tuple, list)):
        return tuple(_sc_num(x) for x in v)
    return v


def _sc_font(f):
    """('Name', -12) / ('Name', -12, 'bold') -> the same font at the scaled size (anything else is left alone)."""
    if isinstance(f, (tuple, list)) and len(f) >= 2 and isinstance(f[1], (int, float)) and not isinstance(f[1], bool):
        n = int(round(f[1] * UI_SC[0])) or (-1 if f[1] < 0 else 1)
        return (f[0], n) + tuple(f[2:])
    return f


def _sc_args(args):
    return tuple(_sc_args(a) if isinstance(a, (tuple, list)) else (_sc_num(a) if isinstance(a, (int, float)) else a) for a in args)


def sc_kw(kind, kw, image=False):
    """Scales the size options of one widget (kind = 'frame' / 'canvas' / 'label' / 'entry'); kw is changed in place."""
    for key in ("padx", "pady", "wraplength", "yscrollincrement"):
        if key in kw:
            kw[key] = _sc_num(kw[key])
    if "font" in kw:
        kw["font"] = _sc_font(kw["font"])
    if kind in ("frame", "canvas") or (kind == "label" and (image or "image" in kw)):
        for key in ("width", "height"):
            if key in kw:
                kw[key] = _sc_num(kw[key])
    return kw


def key_resize(im, size, key_hex, smooth=True):
    """Resizes the frame picture without a pink fringe: the see-through colour is treated as 'no picture' while the rest is
    smoothed, and an edge pixel is then either the picture or exactly the see-through colour (never a blend of the two)."""
    if im.size == tuple(size):
        return im
    k = tuple(int(key_hex.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
    a = np.array(im.convert("RGB"))
    solid = ~np.all(a == k, axis=2)
    rgba = Image.fromarray(np.dstack([a, solid.astype(np.uint8) * 255]), "RGBA")
    out = np.array(rgba.resize(tuple(size), Image.LANCZOS if smooth else Image.NEAREST))
    res = np.where((out[..., 3:4] >= 128), out[..., :3], np.array(k, dtype=np.uint8)).astype(np.uint8)
    return Image.fromarray(res, "RGB")


def ui_img(im, nearest=True):
    """A PIL picture for the main window -> PhotoImage at the window's scale."""
    if UI_SC[0] != 1.0:
        w, h = max(1, S(im.width)), max(1, S(im.height))
        im = im.resize((w, h), Image.NEAREST if (nearest and UI_SC[0] > 1.0) else Image.LANCZOS)
    return ImageTk.PhotoImage(im)


def px1(v):
    """A real pixel distance (from winfo_...) -> the unscaled number the build code works in."""
    return v / UI_SC[0]


def _in_main(w):
    r = APP_ROOT[0]
    if r is None:
        return False
    try:
        return (w if w is not None else r).winfo_toplevel() is r
    except Exception:
        return False


def _is_scaled(w):
    v = getattr(w, "_sc_main", None)
    if v is None:
        v = _in_main(w)
        try:
            w._sc_main = v
        except Exception:
            pass
    return v


def _install_ui_scale():
    raw_conf = tk.Misc.configure

    def kind_of(w):
        if isinstance(w, tk.Canvas):
            return "canvas"
        if isinstance(w, tk.Frame):
            return "frame"
        if isinstance(w, tk.Label):
            return "label"
        return "other"

    def wrap_init(cls):
        orig = cls.__init__

        def init(self, master=None, cnf={}, **kw):
            no = bool(kw.pop("noscale", False))
            use = (not no) and UI_SC[0] != 1.0 and _in_main(master)
            if use:
                if cnf:
                    kw, cnf = dict(cnf, **kw), {}
                sc_kw(kind_of(self), kw)
            orig(self, master, cnf, **kw)
            self._sc_main = bool(use)
        cls.__init__ = init
    for c in (tk.Frame, tk.Label, tk.Canvas, tk.Entry):
        wrap_init(c)

    def conf(self, cnf=None, **kw):
        if UI_SC[0] != 1.0 and (kw or isinstance(cnf, dict)) and _is_scaled(self):
            if isinstance(cnf, dict):
                kw, cnf = dict(cnf, **kw), None
            sc_kw(kind_of(self), kw)
        return raw_conf(self, cnf, **kw)
    tk.Misc.configure = tk.Misc.config = conf

    def wrap_geom(cls, names, keys):
        for nm in names:
            orig = getattr(cls, nm)

            def f(self, cnf={}, __o=orig, **kw):
                if UI_SC[0] != 1.0 and _is_scaled(self):
                    if cnf:
                        kw, cnf = dict(cnf, **kw), {}
                    for k in keys:
                        if k in kw:
                            kw[k] = _sc_num(kw[k])
                return __o(self, cnf, **kw)
            setattr(cls, nm, f)
    wrap_geom(tk.Pack, ("pack_configure", "pack"), ("padx", "pady", "ipadx", "ipady"))
    wrap_geom(tk.Place, ("place_configure", "place"), ("x", "y", "width", "height"))

    orig_create = tk.Canvas._create

    def _create(self, itemType, args, kw):
        if UI_SC[0] != 1.0 and _is_scaled(self):
            args = _sc_args(args)
            if "font" in kw:
                kw = dict(kw, font=_sc_font(kw["font"]))
            if itemType in ("text", "window"):
                kw = dict(kw)
                for k in ("width", "height"):
                    if k in kw:
                        kw[k] = _sc_num(kw[k])
        return orig_create(self, itemType, args, kw)
    tk.Canvas._create = _create

    orig_ic = tk.Canvas.itemconfigure

    def itemconfigure(self, tagOrId, cnf=None, **kw):
        if UI_SC[0] != 1.0 and "font" in kw and _is_scaled(self):
            kw = dict(kw, font=_sc_font(kw["font"]))
        return orig_ic(self, tagOrId, cnf, **kw)
    tk.Canvas.itemconfigure = tk.Canvas.itemconfig = itemconfigure
    return raw_conf


try:
    raw_configure = _install_ui_scale()
except Exception:                                    # (no real tkinter, e.g. the tests: nothing to patch)
    raw_configure = None


def scroll_bg(im, h):
    """The frame picture at another height: only the plain middle strip is stretched, the top and the bottom stay as drawn."""
    W, H = im.size
    if h == H:
        return im
    top, bot = im.crop((0, 0, W, BG_CUT_TOP)), im.crop((0, BG_CUT_BOT, W, H))
    mid_h = h - top.size[1] - bot.size[1]
    out = Image.new(im.mode, (W, h))
    out.paste(top, (0, 0))
    if mid_h > 0:
        strip = im.crop((0, (BG_CUT_TOP + BG_CUT_BOT) // 2, W, (BG_CUT_TOP + BG_CUT_BOT) // 2 + 1)).resize((W, mid_h), Image.NEAREST)
        out.paste(strip, (0, top.size[1]))
    out.paste(bot, (0, top.size[1] + max(0, mid_h)))
    return out
BODY_RECT = (10, 56, 377, 906)             # solid part of the window (x, y, w, h): clicks here are not game clicks
# (key, label, x0, x1) - the four tabs on the dark strip, y 213..236
TABS_X0, TABS_X1, TABS_GAP = 38, 348, 4
TABS = (("main", "Main"), ("mana", "Mana Overlay"), ("extras", "Extras"), ("settings", "Settings"),
        ("cred", "Credit"))


def tab_layout(widths, grow=None):
    """Text widths -> (x0, x1) of each tab so all of them fit on the strip (shrunk evenly if they don't).
    When there is room left over it goes to tab number `grow`, so the tabs always reach the end of the strip."""
    pads = [w + 8 for w in widths]
    room = TABS_X1 - TABS_X0 - TABS_GAP * (len(pads) - 1)
    k = min(1.0, room / float(sum(pads)))
    if grow is not None and k >= 1.0:
        pads[grow] += room - sum(pads)
    out, x = [], float(TABS_X0)
    for w in pads:
        out.append((int(round(x)), int(round(x + w * k))))
        x += w * k + TABS_GAP
    return out

