        self.brew_icon.pack(side="left")
        self.brew_state = self.label(irow, "OFF")
        self.brew_state.pack(side="left", padx=6)
        self._brew_icon_on = False
        self.label(irow, "Active Profile:", font=self.fs).pack(side="left", padx=(12, 4))
